with p as (select unnest(array['b1000000-0000-0000-0000-000000000002','b1000000-0000-0000-0000-000000000005','b1000000-0000-0000-0000-000000000006']::uuid[]) id),
s as (select id from call_series where key='places - c2 weekly call')
select json_build_object(
'series_id',(select id from s),
'last_call',(select json_build_object('id',c.id,'date',c.call_date) from calls c where c.series_id=(select id from s) order by c.call_date desc limit 1),
'agenda_rows',(select json_agg(json_build_object('id',a.id,'for_date',a.for_date,'status',a.status,'based_on',a.based_on_call_id) order by a.for_date) from call_agendas a where a.series_id=(select id from s)),
'call_items',(select json_agg(json_build_object('date',c.call_date,'kind',ci.kind,'prop',ci.property_id,'owner',ci.owner,'desc',ci.description,'due',ci.due_hint) order by ci.property_id, c.call_date) from call_items ci join calls c on c.id=ci.call_id where c.series_id=(select id from s) and not ci.resolved),
'inspection_flagged',(select json_agg(json_build_object('prop',i.property_id,'date',i.inspection_date,'unit',coalesce(ii.unit_number,i.unit_number),'area',i.area,'section',ii.section_name,'item',ii.item_label,'condition',ii.condition,'notes',ii.notes,'disposition_note',ii.disposition_note,'communicated_at',ii.communicated_at,'watch_count',ii.watch_count) order by i.property_id, i.inspection_date) from inspection_items ii join inspections i on i.id=ii.inspection_id where ii.disposition='flagged' and i.property_id in (select id from p)),
'tasks_past_due',(select json_agg(json_build_object('prop',t.property_id,'title',t.title,'desc',left(t.description,300),'status',t.status,'due',t.due_date,'snoozed_until',t.snoozed_until,'follow_up_on',t.follow_up_on) order by t.property_id, t.due_date) from tasks t where t.property_id in (select id from p) and t.status<>'done' and t.due_date < current_date and (t.snoozed_until is null or t.snoozed_until <= current_date)),
'capex_open',(select json_agg(json_build_object('prop',x.property_id,'title',x.title,'category',x.category,'status',x.status,'priority',x.priority,'vendor',x.vendor_name,'start',x.start_date,'target',x.target_completion,'notes',left(x.notes,500),'postponed_at',x.postponed_at,'bids_target',x.bids_target,
   'bids',(select json_agg(json_build_object('vendor',b.vendor_name,'status',b.status,'requested',b.requested_at::date,'received',b.received_at::date)) from capex_bids b where b.project_id=x.id)) order by x.property_id, x.priority, x.title) from capex_projects x where x.property_id in (select id from p) and x.actual_completion is null and coalesce(x.status,'') in ('planning','approved','in_progress'))
) as j;
